func networkDelayTime(times [][]int, n int, k int) int {
	const inf = 1 << 30
	adj := make([][][2]int, n+1)
	for _, t := range times {
		adj[t[0]] = append(adj[t[0]], [2]int{t[1], t[2]})
	}
	dist := make([]int, n+1)
	for i := range dist {
		dist[i] = inf
	}
	dist[k] = 0
	done := make([]bool, n+1)
	for step := 0; step < n; step++ {
		u := 0
		for v := 1; v <= n; v++ {
			if !done[v] && dist[v] < inf && (u == 0 || dist[v] < dist[u]) {
				u = v
			}
		}
		if u == 0 {
			break
		}
		done[u] = true
		for _, e := range adj[u] {
			if d := dist[u] + e[1]; d < dist[e[0]] {
				dist[e[0]] = d
			}
		}
	}
	worst := 0
	for v := 1; v <= n; v++ {
		if dist[v] == inf {
			return -1
		}
		if dist[v] > worst {
			worst = dist[v]
		}
	}
	return worst
}

