func TestStrStrMatchesStandardLibrary(t *testing.T) {
	alphabet := "aab"
	texts := []string{"", "a", "aab", "aaabaab", "baaabaaab"}
	for _, text := range texts {
		for i := 0; i <= len(alphabet); i++ {
			needle := alphabet[:i]
			if got, want := strStr(text, needle), strings.Index(text, needle); got != want {
