// The naive scan is quadratic on this input and will not finish; only a
// solution that reuses the prefix table gets through it.
func TestStrStrAdversarialRepeats(t *testing.T) {
	haystack := strings.Repeat("a", 200000)
	needle := strings.Repeat("a", 20000) + "b"
	if got := strStr(haystack, needle); got != -1 {
		t.Fatalf("no-match case = %d, want -1", got)
	}
	if got := strStr(haystack+"b", needle); got != 180000 {
		t.Fatalf("match case = %d, want 180000", got)
	}
}

