func TestFenwickMatchesBruteForce(t *testing.T) {
	const n = 200
	nums := make([]int, n)
	seed := 12345
	next := func() int {
		seed = (seed*1103515245 + 12345) & 0x7fffffff
		return seed
	}
	for i := range nums {
		nums[i] = next()%100 - 50
	}
	plain := append([]int(nil), nums...)
	f := NewFenwick(nums)
	for op := 0; op < 2000; op++ {
		i := next() % n
		delta := next()%20 - 10
		f.Add(i, delta)
		plain[i] += delta
		l := next() % n
		r := l + next()%(n-l)
		want := 0
		for k := l; k <= r; k++ {
			want += plain[k]
		}
		if got := f.Sum(l, r); got != want {
			t.Fatalf("Sum(%d,%d) = %d, want %d", l, r, got, want)
		}
	}
}

// A tree that answers a range sum by walking the array is fast enough above but
// not here: this needs the logarithmic update and query.
func TestFenwickLargeIsFast(t *testing.T) {
	const n = 100000
	f := NewFenwick(make([]int, n))
	total := 0
	for i := 0; i < n; i++ {
		f.Add(i, i%7)
		total += i % 7
	}
	if got := f.Sum(0, n-1); got != total {
		t.Fatalf("full sum = %d, want %d", got, total)
	}
	for q := 0; q < 100000; q++ {
		l := q % n
		if got := f.Sum(l, l); got != l%7 {
			t.Fatalf("Sum(%d,%d) = %d, want %d", l, l, got, l%7)
		}
	}
}

